	@Test
	@Timeout(180)
	void aRollbackKeepsTheCheckpointedPrefixAndDiscardsTheOpenChunk() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			long checkpoints = backing.noneIngestionMetrics().checkpoints();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				int subjects = 0;
				while (backing.noneIngestionMetrics().checkpoints() == checkpoints) {
					addSubjects(writer, subjects, subjects + 1_000);
					subjects += 1_000;
				}
				assertThat(backing.isInitialRunImportActive()).isTrue();
				addSubjects(writer, 1_000_000, 1_000_100);
				writer.rollback();
			}
			assertThat(backing.isInitialRunImportActive()).isFalse();
			assertThat(new File(directory, LmdbInitialRunImport.MARKER_FILE_NAME)).doesNotExist();
			try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
				long size = reader.size();
				assertThat(size).as("the checkpointed prefix survives").isPositive();
				try (var statements = reader.getStatements(subject(1_000_000), null, null, false)) {
					assertThat(statements.stream().count()).as("the open chunk is discarded").isZero();
				}
				try (var statements = reader.getStatements(null, SHARED, SHARED, false)) {
					assertThat(statements.stream().count()).isEqualTo(size / 2);
				}
			}
		} finally {
			sail.shutDown();
		}
	}

