	@Test
	@Timeout(120)
	void aLeftoverMarkerResetsTheStoreToEmptyOnStartup() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config().setInitialRunImportEnabled(false));
		sail.init();
		try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
			writer.begin(IsolationLevels.NONE);
			addSubjects(writer, 0, 100);
			writer.commit();
		} finally {
			sail.shutDown();
		}
		Files.createFile(new File(directory, LmdbInitialRunImport.MARKER_FILE_NAME).toPath());
		Files.createDirectories(new File(directory, LmdbInitialRunImport.RUN_DIRECTORY_NAME).toPath());

		LmdbStore reopened = new LmdbStore(directory, config());
		reopened.init();
		try {
			assertThat(new File(directory, LmdbInitialRunImport.MARKER_FILE_NAME)).doesNotExist();
			assertThat(new File(directory, LmdbInitialRunImport.RUN_DIRECTORY_NAME)).doesNotExist();
			try (LmdbStoreConnection reader = (LmdbStoreConnection) reopened.getConnection()) {
				assertThat(reader.size()).as("an interrupted import leaves an empty store").isZero();
			}
			try (LmdbStoreConnection writer = (LmdbStoreConnection) reopened.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				addSubjects(writer, 0, 200);
				assertThat(reopened.getBackingStore().isInitialRunImportActive())
						.as("the reset store is eligible again")
						.isTrue();
				writer.commit();
			}
			assertImported(reopened, 200);
		} finally {
			reopened.shutDown();
		}
	}

	private static void addSubjects(LmdbStoreConnection writer, int from, int to) {
		for (int i = from; i < to; i++) {
			writer.addStatement(subject(i), SHARED, SHARED);
			writer.addStatement(subject(i), SHARED, VF.createLiteral("value " + i), (Resource) GRAPH);
		}
	}

	private static IRI subject(int i) {
		return VF.createIRI("http://example.com/run-import/subject/" + i);
	}

	private static void assertImported(LmdbStore sail, int subjects) {
		try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
			assertThat(reader.size()).isEqualTo(2L * subjects);
			assertThat(reader.size(GRAPH)).isEqualTo(subjects);
			try (var statements = reader.getStatements(null, SHARED, SHARED, false)) {
				assertThat(statements.stream().count()).isEqualTo(subjects);
			}
			for (int i : new int[] { 0, subjects / 2, subjects - 1 }) {
				try (var statements = reader.getStatements(subject(i), null, null, false)) {
					assertThat(statements.stream().count()).isEqualTo(2);
				}
				try (var statements = reader.getStatements(null, null, VF.createLiteral("value " + i), false)) {
					assertThat(statements.stream().count()).as("value lookup records exist").isEqualTo(1);
				}
			}
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc,ospc").setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setBulkOperationSize(64);
	}

	private static final class FailingLookupStore extends LmdbStore {
		private FailingLookupValueStore values;

		private FailingLookupStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchEnabled,
					(valueDir, storeProperties, settings) -> {
						values = new FailingLookupValueStore(valueDir, storeProperties, settings);
						return values;
					}, TripleStore::new);
		}
	}

	private static final class FailingLookupValueStore extends ValueStore {
		private volatile int mapFullsRemaining;
		private volatile int mapFullsInjected;

		private FailingLookupValueStore(File directory, StoreProperties properties, LmdbStoreConfig config)
				throws IOException {
			super(directory, properties, config);
		}

		@Override
		long writeDeferredLookups(LmdbDeferredValueLookups.Source source) throws IOException {
			if (mapFullsRemaining > 0) {
				mapFullsRemaining--;
				mapFullsInjected++;
				LmdbUtil.E(MDB_MAP_FULL);
			}
			return super.writeDeferredLookups(source);
		}
	}
